-- Varikotsele (HARD) USMLE uslubidagi klinik vinyetka test bankini to'ldirish — 20 ta savol.
-- USMLE bo'limi shulardan random 5 tasini shuffle qilib chiqaradi.
UPDATE public.dars_tarkibi
SET usmle_savollar = $usmle$[{"vinyetka":"19-yoshli yigit profilaktik ko'rikda chap mosjonkada og'riqsiz shish bilan murojaat qiladi. Tik turganda 'qurt to'plami' kabi tuguncha palpatsiya qilinadi, yotganda kamayadi. Valsalva sinamasi tuguncha kattalashishini kuchaytiradi.","savol":"Eng ehtimoliy tashxis qaysi?","variantlar":["Gidrosele","Varikosele","Spermatosele","Ingvinal gerniya"],"togri":1,"izoh":"Tik turganda ko'rinadigan, Valsalva bilan kuchayadigan, yotganda kamayadigan venoz tugunchalar — varikoselening klassik klinik ko'rinishi."},{"vinyetka":"32-yoshli erkak 2 yildan beri bola ko'rolmayotgani sababli murojaat qiladi. Fizik tekshiruvda chap mosjonkada III-daraja varikosele aniqlanadi. Spermogramma oligozoospermiya va astenozoospermiyani ko'rsatadi.","savol":"Varikoselening spermatogenezga ta'sirida asosiy patofiziologik mexanizm nima?","variantlar":["Bakterial infeksiya","Intratestikulyar haroratning oshishi (issiqlik almashinuvi buzilishi)","Gormonal substitutsiya yetishmovchiligi","Uretra torayishi"],"togri":1,"izoh":"Varikoselede pampiniform pleksusning issiqlik almashinuvi funksiyasi buziladi, bu intratestikulyar haroratni oshirib spermatogenezni bevosita buzadi."},{"vinyetka":"58-yoshli erkak bir necha hafta oldin to'satdan paydo bo'lgan o'ng tomonlama mosjonka shishi bilan murojaat qiladi. Anamnezda vazn yo'qotish va gematuriya bor.","savol":"Keyingi eng to'g'ri tekshiruv qadami nima?","variantlar":["Faqat kuzatuv","Qorin/retroperitoneal UTT yoki KT (buyrak massasi uchun)","Antibiotikoterapiya boshlash","Darhol varikoselektomiya"],"togri":1,"izoh":"Keskin boshlangan o'ng tomonlama varikosele, ayniqsa boshqa belgilar (gematuriya, vazn yo'qotish) bilan birga bo'lsa, retroperitoneal massa (buyrak hujayrali karsinoma)ni inkor etish uchun tasvirlash tekshiruvi talab qiladi."},{"vinyetka":"16-yoshli o'smir profilaktik tekshiruvda chap mosjonkada faqat Valsalva sinamasi vaqtida palpatsiya qilinadigan tuguncha aniqlanadi, ko'zga ko'rinmaydi.","savol":"Dubin-Amelar tasnifi bo'yicha bu qaysi daraja?","variantlar":["Subklinik","I-daraja","II-daraja","III-daraja"],"togri":1,"izoh":"Faqat Valsalva sinamasi vaqtida palpatsiya qilinadigan, ko'rinmaydigan varikosele I-daraja (yengil) hisoblanadi."},{"vinyetka":"27-yoshli erkak infertillik bo'yicha tekshirilmoqda. Chap mosjonkada klinik varikosele va spermogrammada patologik o'zgarishlar aniqlandi. Xotini fertillik nuqtai nazaridan sog'lom.","savol":"Bu bemorda jarrohlik davolashga ko'rsatma bormi?","variantlar":["Yo'q, faqat dorivor davo kerak","Ha — klinik varikosele + patologik spermogramma + bola ko'rishga intilish birikmasi ko'rsatma hisoblanadi","Yo'q, faqat 40 yoshdan keyin","Ha, lekin faqat ikkala tomon zararlangan bo'lsa"],"togri":1,"izoh":"Klinik (palpatsiya bilan aniqlanadigan) varikosele, patologik spermogramma va er-xotinning bola ko'rishga intilishi — varikoselektomiyaga asosiy ko'rsatma."},{"vinyetka":"45-yoshli erkak bemor faqat Doppler UTT'da aniqlangan, palpatsiya qilinmaydigan varikosele bilan murojaat qiladi. Spermogramma normal, bola tug'dirish rejasi yo'q.","savol":"Eng to'g'ri boshqaruv taktikasi qaysi?","variantlar":["Darhol mikroxirurgik varikoselektomiya","Dinamik kuzatuv, jarrohliksiz","Skleroterapiya","Bilateral orxiektomiya"],"togri":1,"izoh":"Subklinik (faqat instrumental aniqlangan) varikosele, normal spermogramma va bola tug'dirish rejasi yo'q bo'lganda jarrohlik tavsiya etilmaydi — dinamik kuzatuv yetarli."},{"vinyetka":"Talaba varikoselektomiya usullarini solishtirmoqda. Bir usulda urug' bezi arteriyasi saqlanmaydi va gidrosele xavfi 3-30% ni tashkil qiladi.","savol":"Bu tasvir qaysi usulga to'g'ri keladi?","variantlar":["Mikroxirurgik subingvinal usul","Konvensional ingvinal (klassik chov) usul","Radiologik embolizatsiya","Laparoskopik usul (arteriya saqlanadigan variant)"],"togri":1,"izoh":"Konvensional ingvinal usulda arteriya odatda saqlanmaydi va gidrosele xavfi 3-30% (o'rtacha yuqoriroq) ni tashkil qiladi — mikroxirurgik usuldan farqli."},{"vinyetka":"Jarroh varikoselektomiya paytida operatsion mikroskop yordamida urug' bezi arteriyasi, limfa tomirlari va vas deferensni ehtiyotkorlik bilan ajratib, faqat kengaygan venalarni bog'laydi.","savol":"Bu qaysi usulning tasviri va uning asosiy afzalligi nima?","variantlar":["Palomo usuli — eng tez bajariladi","Mikroxirurgik subingvinal/ingvinal usul — eng past qaytalanish va gidrosele ko'rsatkichlari","Laparoskopik usul — narxi arzon","Venografiya — diagnostik usul, davolash emas"],"togri":1,"izoh":"Mikroxirurgik usulning asosiy afzalligi — arteriya va limfa tomirlarini saqlab qolish orqali gidrosele (0%) va qaytalanish (0.5-1%) ko'rsatkichlarini minimallashtirish."},{"vinyetka":"29-yoshli erkak varikoselektomiyadan 2 hafta o'tib, mosjonkada og'riqsiz suyuqlik to'planishi bilan murojaat qiladi. Transilluminatsiya pozitiv.","savol":"Bu asorat qaysi tomir tizimining shikastlanishi bilan bog'liq?","variantlar":["Arteriya","Limfa tomirlari","Vas deferens","Nerv"],"togri":1,"izoh":"Operatsiya paytida limfa tomirlarining bog'lanishi (limfostaz) postoperativ gidroselening asosiy sababi hisoblanadi."},{"vinyetka":"35-yoshli erkak varikoselektomiyadan keyin urug' bezi hajmining kichrayishi va spermatogenez yomonlashishi bilan murojaat qiladi.","savol":"Bu asoratning eng ehtimoliy sababi nima?","variantlar":["Urug' bezi arteriyasining bilmasdan shikastlanishi/bog'lanishi","Ortiqcha jismoniy faollik","Antibiotik qabul qilinmaganligi","Operatsiyadan keyin erta jinsiy aloqa"],"togri":0,"izoh":"Urug' bezi arteriyasi ingichka (1.0-1.5 mm) bo'lgani uchun mikroskopsiz usullarda shikastlanish/bog'lanish xavfi yuqori, bu atrofiya va spermatogenez buzilishiga olib kelishi mumkin."},{"vinyetka":"Tadqiqotchi varikoseleli va sog'lom erkaklarning urug' suyuqligini solishtirmoqda va varikoseleli guruhda yuqori darajadagi reaktiv oksigen turlari (oksidativ stress) aniqlaydi.","savol":"Bu topilma spermatozoidlarga qanday ta'sir qiladi deb kutiladi?","variantlar":["Harakatchanlikni oshiradi","DNK fragmentatsiyasi va apoptozni kuchaytiradi","Hajmni kattalashtiradi","Hech qanday ta'siri yo'q"],"togri":1,"izoh":"Yuqori oksidativ stress spermatozoidlar DNKsining fragmentatsiyasini kuchaytiradi va apoptozga moyillikni oshiradi — bu fertillikka salbiy ta'sir qiladi."},{"vinyetka":"22-yoshli erkak shifokorga sovuq kabinetda tekshirilgan va varikosele aniqlanmagan, ammo issiq xonada qaytadan tekshirilganda chap mosjonkada aniq tuguncha topilgan.","savol":"Bu farqning sababi nima?","variantlar":["Sovuqda qon bosimi oshadi","Sovuqda kremaster mushagi qisqarib varikoseleni yashiradi","Issiq xonada vena kengayadi va aniq ko'rinmaydi","Farq tasodifiy, ahamiyati yo'q"],"togri":1,"izoh":"Sovuq sharoitda kremaster mushagining qisqarishi moyakni ko'tarib varikoseleni yashirishi mumkin, shu sabab tekshiruv issiq xonada o'tkazilishi tavsiya etiladi."},{"vinyetka":"40-yoshli erkak surunkali bepushtlik bo'yicha tekshirilmoqda. Spermogrammada konsentratsiya, harakatchanlik va morfologiyaning barchasi pasaygan.","savol":"Bu spermogramma topilmasi qaysi sindrom bilan tavsiflanadi?","variantlar":["Azoospermiya","OAT-sindromi (Oligo-Astheno-Teratozoospermiya)","Aspermiya","Hiperspermiya"],"togri":1,"izoh":"Konsentratsiya (oligo), harakatchanlik (astheno) va morfologiya (terato)ning barchasi birgalikda pasayishi OAT-sindromi deb ataladi, varikoselening klassik laborator ko'rinishi."},{"vinyetka":"Shifokor varikoseleli bemorga ultratovush tayinlamoqda, lekin adabiyotlarda diametr bo'yicha yagona chegara yo'qligini tushuntiradi.","savol":"Bu holatda tashxis qo'yishda qaysi usul ustun (birinchi) hisoblanadi?","variantlar":["Ultratovush diametri","Klinik (palpatsiya) tekshiruv","KT","Venografiya"],"togri":1,"izoh":"UTT'da vena diametri bo'yicha universal chegara yo'qligi sababli, varikosele tashxisi birinchi navbatda klinik (palpatsiya) tekshiruvga asoslanadi, UTT yordamchi vosita."},{"vinyetka":"26-yoshli erkak chap mosjonkada og'riq bilan murojaat qiladi, og'riq kechqurun uzoq tik turgandan keyin kuchayadi va yotganda yo'qoladi. Konservativ chora-tadbirlar (NSPVD, support) yordam bermayapti.","savol":"Bu bemor uchun keyingi mos qadam nima?","variantlar":["Faqat kuzatuv davom etadi","Varikoselektomiyani ko'rib chiqish (konservativ davo samarasiz og'riq ko'rsatma hisoblanadi)","Darhol antibiotik","Testosteron in'eksiyasi"],"togri":1,"izoh":"Konservativ chora-tadbirlarga javob bermaydigan mosjonka og'rig'i varikoselektomiya uchun mustaqil ko'rsatmalardan biri hisoblanadi."},{"vinyetka":"31-yoshli erkak past testosteron darajasi (250 ng/dL) va klinik varikosele bilan murojaat qiladi. U charchoq va libido pasayishidan shikoyat qiladi.","savol":"Bu bemorda varikoselektomiya nimaga yordam berishi mumkin?","variantlar":["Hech qanday gormonal ta'sir bo'lmaydi","Leydig hujayralari funksiyasini yaxshilab, serum testosteron darajasini oshirishi mumkin","Faqat spermatogenezga ta'sir qiladi, gormonlarga emas","Testosteron darajasini pasaytiradi"],"togri":1,"izoh":"Past testosteron bilan murojaat qilgan bemorlarda mikroxirurgik varikoselektomiya Leydig hujayralari funksiyasini yaxshilab, serum testosteron darajasini sezilarli oshirishi mumkin."},{"vinyetka":"19-yoshli o'smir yillik tekshiruvda chap mosjonkada II-daraja varikosele va o'ng moyakka solishtirganda chap moyak hajmining sezilarli kichikligi (asimmetriya) aniqlanadi.","savol":"Bu topilma qaysi qarorni qo'llab-quvvatlaydi?","variantlar":["Faqat kuzatuv, hech narsa qilinmaydi","Jarrohlik (varikoselektomiya)ni ko'rib chiqish — progressiv asimmetriya ko'rsatma hisoblanadi","Darhol orxiektomiya","Faqat gormonal terapiya"],"togri":1,"izoh":"O'smirlarda progressiv urug' bezi hajmi kichrayishi yoki ikkala tomon orasida sezilarli asimmetriya varikoselektomiyaga ko'rsatma hisoblanadi."},{"vinyetka":"33-yoshli erkak varikoselektomiyadan 4 oy o'tib nazorat spermogrammasini topshiradi.","savol":"Operatsiyadan keyin spermogramma nazorati odatda qancha vaqtdan keyin o'tkaziladi?","variantlar":["1 hafta","3-6 oy","5 yil","Hech qachon kerak emas"],"togri":1,"izoh":"Spermatogenez tiklanish davrini hisobga olib, nazorat spermogrammasi odatda 3-6 oydan keyin o'tkaziladi."},{"vinyetka":"Radiolog varikosele bilan og'rigan bemorga noinvaziv, arteriya/limfa tomirlariga tegmaydigan, gidrosele xavfi 0% bo'lgan, lekin qaytalanish xavfi 15-25% bo'lgan usulni taklif qiladi.","savol":"Bu qaysi davolash usuli?","variantlar":["Mikroxirurgik varikoselektomiya","Radiologik embolizatsiya","Palomo usuli","Laparoskopik usul"],"togri":1,"izoh":"Radiologik embolizatsiya arteriya/limfaga tegmagani uchun gidrosele xavfi 0%, lekin texnik tabiati tufayli qaytalanish xavfi 15-25% bilan boshqa usullardan yuqoriroq."},{"vinyetka":"24-yoshli erkak mosjonkada o'ng tomonlama, palpatsiya qilinadigan tuguncha bilan murojaat qiladi. Chap tomonda hech narsa topilmaydi. Anamnez va boshqa tekshiruvlar normal.","savol":"Bu nostandart (faqat o'ng tomonlama) topilma haqida qaysi gap to'g'ri?","variantlar":["Bu juda oddiy holat, qo'shimcha tekshiruv kerak emas","Kamdan-kam uchraydi, retroperitoneal patologiyani inkor etish uchun qo'shimcha tasvirlash zarur","Bu doim saraton degani","Faqat ayollarda uchraydigan holat"],"togri":1,"izoh":"Izolyatsiyalangan o'ng tomonlama varikosele kamdan-kam uchraydi va retroperitoneal massa (masalan, buyrak o'smasi)dan shubhalanib, qo'shimcha tasvirlash tekshiruvi o'tkazilishi kerak."}]$usmle$::jsonb,
    updated_at = now()
WHERE dars_slug = 'h-varikotsele-kasalligi';
